def find_the_correct_casing(
    key: str, data_keys: tuple[Any, ...]
) -> str | None:
    if not isinstance(key, str) or key in data_keys:
        return key
    for k in data_keys:
        if not isinstance(k, str):
            return None
        if k.lower() == key.lower():
            return k
        if k.replace(" ", "_").lower() == key.lower():
            return k
    return None


